package cn.pegasus.setup;
import android.app.Activity;import android.os.Bundle;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;
public final class TutorialActivity extends Activity {
 ScrollView page;int dp(int value){return (int)(value*getResources().getDisplayMetrics().density+.5f);}
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN,WindowManager.LayoutParams.FLAG_FULLSCREEN);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);boolean controller=getIntent().getBooleanExtra("controller",false);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(KpaTheme.BG);LinearLayout toolbar=new LinearLayout(this);toolbar.setGravity(Gravity.CENTER_VERTICAL);toolbar.setPadding(dp(KpaLayout.EDGE),dp(6),dp(KpaLayout.EDGE),dp(6));TextView title=new TextView(this);title.setText(controller?"手柄配置教程":"模拟器设置教程");title.setTextColor(KpaTheme.TEXT);title.setTextSize(KpaLayout.TITLE_TEXT);title.setTypeface(null,Typeface.BOLD);toolbar.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button close=new Button(this);close.setText("X");close.setTextSize(17);close.setTextColor(KpaTheme.BG);close.setContentDescription("关闭教程，B返回");GradientDrawable background=new GradientDrawable();background.setColor(KpaTheme.TEXT);background.setCornerRadius(dp(18));close.setBackground(background);close.setPadding(0,0,0,0);toolbar.addView(close,new LinearLayout.LayoutParams(dp(40),dp(40)));close.setOnClickListener(v->finish());root.addView(toolbar,new LinearLayout.LayoutParams(-1,dp(KpaLayout.DIALOG_HEADER)));page=new ScrollView(this);page.setFillViewport(true);LinearLayout article=new LinearLayout(this);article.setOrientation(1);article.setPadding(dp(KpaLayout.EDGE),dp(8),dp(KpaLayout.EDGE),dp(KpaLayout.EDGE));page.addView(article,new ScrollView.LayoutParams(-1,-2));root.addView(page,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);try{java.io.BufferedReader reader=new java.io.BufferedReader(new java.io.InputStreamReader(getAssets().open("tutorials/"+(controller?"controller":"emulators")+".md"),"UTF-8"));String line;LinearLayout section=null;while((line=reader.readLine())!=null){line=line.trim();if(line.isEmpty()||line.matches("-+"))continue;boolean heading=line.startsWith("#");if(heading&&line.replaceFirst("^#+ *", "").replace("【", "").replace("】", "").equals("模拟器设置教程"))continue;if(heading||section==null){section=new LinearLayout(this);section.setOrientation(1);section.setPadding(dp(14),dp(10),dp(14),dp(10));GradientDrawable card=new GradientDrawable();card.setColor(KpaTheme.PANEL);card.setCornerRadius(dp(KpaLayout.RADIUS));section.setBackground(card);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(10));article.addView(section,lp);}TextView paragraph=new TextView(this);paragraph.setText(line.replaceFirst("^#+ *","").replace("`","").replaceFirst("^- ","• "));paragraph.setTextSize(heading?KpaLayout.SECTION_TEXT:KpaLayout.BODY_TEXT);paragraph.setTextColor(heading?KpaTheme.TEXT:line.contains("base.apk")?KpaTheme.ERROR:KpaTheme.TEXT);paragraph.setPadding(0,dp(2),0,dp(4));paragraph.setLineSpacing(dp(2),1);if(heading)paragraph.setTypeface(null,Typeface.BOLD);section.addView(paragraph);}reader.close();TextView source=new TextView(this);source.setText("教程来源：天马G Konkr KPA 定制版 游戏链接+安装说明+快捷键说明 20260821.md");source.setTextSize(11);source.setTextColor(KpaTheme.MUTED);article.addView(source);}catch(Exception e){TextView error=new TextView(this);error.setText("教程读取失败："+e.getMessage());error.setTextColor(KpaTheme.ERROR);article.addView(error);}}

 @Override public boolean onKeyDown(int code,KeyEvent event){if(code==KeyEvent.KEYCODE_BUTTON_B){if(event.getRepeatCount()==0)finish();return true;}if(code==KeyEvent.KEYCODE_DPAD_UP||code==KeyEvent.KEYCODE_DPAD_DOWN){page.scrollBy(0,dp(code==KeyEvent.KEYCODE_DPAD_UP?-100:100));return true;}return super.onKeyDown(code,event);}
 @Override public boolean onKeyUp(int code,KeyEvent event){if(code==KeyEvent.KEYCODE_BUTTON_B||code==KeyEvent.KEYCODE_DPAD_UP||code==KeyEvent.KEYCODE_DPAD_DOWN)return true;return super.onKeyUp(code,event);}
 @Override protected void onDestroy(){super.onDestroy();}
}
